use verus::prelude::*;

verus! {

    /// Given an array `arr` of 32-bit signed integers and an integer `elem`,
    /// returns a new `Vec<i32>` of length `2 * arr.len()` such that
    /// for all k < arr.len():
    ///   result[2*k]     == elem
    ///   result[2*k + 1] == arr[k]
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            // length requirement
            result.len() == 2 * arr.len() &&
            // interleaving requirement
            forall |k: usize| k < arr.len() ==>
                result[2*k] == elem && result[2*k + 1] == arr[k]
    {
        // We'll build up `result` by pushing two elements per iteration.
        let mut result: Vec<i32> = Vec::new();
        // Reserve capacity for efficiency (optional, but does not affect verification).
        result.reserve(2 * arr.len());

        let mut i: usize = 0;
        // Loop until we've processed all elements of `arr`.
        while i < arr.len() {
            // Loop invariants:
            // 1. i is between 0 and arr.len().
            invariant i <= arr.len();
            // 2. We've pushed exactly 2*i elements so far.
            invariant result.len() == 2 * i;
            // 3. Those 2*i elements satisfy the interleaving property
            //    for all indices j < i.
            invariant forall |j: usize| j < i ==>
                result[2*j] == elem && result[2*j + 1] == arr[j];
            // Termination metric: the remaining number of elements to process.
            decreases arr.len() - i;

            // Push `elem`, then the next element of `arr`.
            result.push(elem);
            result.push(arr[i]);
            i += 1;
        }

        result
    }

}